// Helper function to calculate the sum of ASCII values for uppercase characters
function SumAsciiUpper(s: string): int
    requires s != null
    ensures Result >= 0
{
    var total: int := 0;
    var i: int := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant total >= 0
    {
        if s[i] >= 'A' && s[i] <= 'Z' {
            total := total + (s[i] as int);
        }
        i := i + 1;
    }
    return total;
}
